# Standalone, stdlib-free, deterministic, exact rational arithmetic, fail-closed.
# No dunder overrides, no I/O, no imports. RESULT = 'PASS' or 'FAIL'.

WITNESS = {
    'n': 30030,
    'factorization_n': [[2, 1], [3, 1], [5, 1], [7, 1], [11, 1], [13, 1]],
    'factorization_n1': [[59, 1], [509, 1]],
    'omega_n': 6,
    'omega_n1': 2,
    'alpha_lower_num': 4587520,
    'alpha_upper_num': 4587521,
    'alpha_den': 30030,
    'series_terms': 200,
}


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def frac(num, den):
    # Normalize exact rational; returns (num, den) with den > 0.
    if den == 0:
        raise ArithmeticError
    if den < 0:
        num, den = -num, -den
    g = gcd(abs(num), den)
    if g == 0:
        g = 1
    return (num // g, den // g)


def fadd(a, b):
    return frac(a[0] * b[1] + b[0] * a[1], a[1] * b[1])


def fsub(a, b):
    return frac(a[0] * b[1] - b[0] * a[1], a[1] * b[1])


def fmul(a, b):
    return frac(a[0] * b[0], a[1] * b[1])


def fdiv(a, b):
    if b[0] == 0:
        raise ArithmeticError
    return frac(a[0] * b[1], a[1] * b[0])


def fgt(a, b):
    return a[0] * b[1] > b[0] * a[1]


def fpow(a, k):
    r = (1, 1)
    for _ in range(k):
        r = fmul(r, a)
    return r


def is_prime(p):
    if p < 2:
        return False
    i = 2
    while i * i <= p:
        if p % i == 0:
            return False
        i += 1
    return True


def factorization_check(fact, value):
    prod = 1
    for p, e in fact:
        if not is_prime(p) or e != 1:
            return False
        prod *= p ** e
    return prod == value


def log_bounds(x, terms):
    # Strict rational bounds on log(x), x > 1, via log(x) = 2*atanh(t), t=(x-1)/(x+1).
    # Alternating series: partial sum through index 2*terms-1 is a strict LOWER bound;
    # adding the positive first omitted term gives a strict UPPER bound.
    if x <= 1:
        raise ArithmeticError
    t = frac(x - 1, x + 1)
    s = (0, 1)
    for j in range(terms):
        term = fdiv(fpow(t, 2 * j + 1), (2 * j + 1, 1))
        if j % 2 == 0:
            s = fadd(s, term)
        else:
            s = fsub(s, term)
    lower = fmul(s, (2, 1))
    tail = fdiv(fpow(t, 2 * terms + 1), (2 * terms + 1, 1))
    upper = fadd(lower, fmul(tail, (2, 1)))
    return lower, upper


def verify(w):
    n = w['n']
    if n != 30030:
        return False
    fn = w['factorization_n']
    fn1 = w['factorization_n1']
    if not factorization_check(fn, n):
        return False
    if not factorization_check(fn1, n + 1):
        return False
    pn = [p for p, e in fn]
    pn1 = [p for p, e in fn1]
    if len(set(pn)) != len(pn) or len(set(pn1)) != len(pn1):
        return False
    if pn != [2, 3, 5, 7, 11, 13] or pn1 != [59, 509]:
        return False
    if w['omega_n'] != len(pn) or w['omega_n1'] != len(pn1):
        return False
    # omega(30030)=6, omega(30031)=2 verified exactly.
    # Interval check: alpha in [alpha_lower_num/den, alpha_upper_num/den];
    # beta = n+1; require strict: 8*log(alpha)/beta > 3/2 across the interval,
    # with strict rational log envelopes, aborting on any unresolved sign.
    terms = w['series_terms']
    if terms <= 0:
        return False
    a_lo = frac(w['alpha_lower_num'], w['alpha_den'])
    a_hi = frac(w['alpha_upper_num'], w['alpha_den'])
    zero = (0, 1)
    if fgt(zero, a_lo) or not fgt(a_hi, a_lo):
        return False
    beta = (n + 1, 1)
    lo1, hi1 = log_bounds(a_lo[0], terms)
    lon, hin = log_bounds(n, terms)
    log_alpha_lo = fsub(lo1, hin)      # strict LOWER bound on log(a_lo)
    lo2, hi2 = log_bounds(a_hi[0], terms)
    log_alpha_hi = fsub(hi2, lon)      # strict UPPER bound on log(a_hi)
    if not fgt(log_alpha_lo, zero):
        return False
    lower_env = fdiv(fmul((8, 1), log_alpha_lo), beta)
    upper_env = fdiv(fmul((8, 1), log_alpha_hi), beta)
    if not fgt(lower_env, (3, 2)):
        return False
    if not fgt(upper_env, lower_env):
        return False
    return True


RESULT = 'PASS' if verify(WITNESS) else 'FAIL'
